import{H as e,V as t,et as ee,j as n}from"./chunks/framework.CW0zsFMp.js";import{$a as r,Aa as i,Ba as a,Ca as o,Da as s,Ea as c,Fa as l,Ga as u,Ha as d,Ia as f,Ja as p,Ka as m,La as h,Ma as g,Na as _,Oa as v,Pa as y,Qa as b,Ra as x,Ta as S,Ua as C,Va as w,Wa as T,Xa as E,Ya as D,Za as O,_o as te,ao as k,bo as A,co as j,do as M,eo as N,fo as P,go as F,ho as I,io as L,ja as R,ka as z,lo as B,mo as V,no as H,oo as U,po as W,qa as G,ro as K,so as q,to as J,uo as Y,vo as X,wa as Z,yo as Q,za as ne}from"./chunks/assets.BxHYjuf8.js";var $=JSON.parse(`{"title":"分库分表","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/sharding.md","filePath":"mysql/sharding.md"}`),re={name:`mysql/sharding.md`};function ie(n,$,re,ie,ae,oe){return ee(),t(`div`,null,[...$[0]||=[e(`<h1 id="分库分表" tabindex="-1">分库分表 <a class="header-anchor" href="#分库分表" aria-label="Permalink to “分库分表”">​</a></h1><h2 id="_1-介绍" tabindex="-1">1.介绍 <a class="header-anchor" href="#_1-介绍" aria-label="Permalink to “1.介绍”">​</a></h2><p><img src="`+A+`" alt="11a9f609ffc848ff87b0f273f569693epng" width="1511" height="694"></p><p><img src="`+Q+`" alt="06c9e722c65347e7962c2182702a6f09png" width="1439" height="562"></p><p><img src="`+X+`" alt="699809fa9d6840de8aafe2588f4b7ffdpng" width="1561" height="684"></p><p><img src="`+te+`" alt="79d332f79c4d44d2a73289bcd32ae2c1png" width="1509" height="710"></p><p><img src="`+F+`" alt="9bfd999f8b564df9a421fc95468a9f8epng" width="1504" height="667"></p><h2 id="_2-mycat概述" tabindex="-1">2.Mycat概述 <a class="header-anchor" href="#_2-mycat概述" aria-label="Permalink to “2.Mycat概述”">​</a></h2><p>Mycat是开源的、活跃的、基于Java语言编写的MySQL<strong>数据库中间件</strong>。可以像使用mysql一样来使用mycat，对于开发人员来说根本感觉 不到mycat的存在。</p><p><img src="`+I+`" alt="a1d433c1ad0944659b2eef61bdc76267png" width="572" height="535"></p><p>优势：</p><ul><li><p>性能可靠稳定</p></li><li><p>强大的技术团队</p></li><li><p>体系完善</p></li><li><p>社区活跃</p></li></ul><h3 id="_2-1-安装" tabindex="-1">2.1 安装 <a class="header-anchor" href="#_2-1-安装" aria-label="Permalink to “2.1 安装”">​</a></h3><p>Mycat是采用java语言开发的开源的数据库中间件，支持Windows和Linux运行环境，下面介绍MyCat的Linux中的环境搭建。我们需要在 准备好的服务器中安装如下软件：</p><ol><li><p>MySQL</p></li><li><p>JDK</p></li><li><p>Mycat</p></li></ol><table tabindex="0"><thead><tr><th>服务器</th><th>安装的软件</th><th>说明</th></tr></thead><tbody><tr><td>192.168.200.210</td><td>JDK、Mycat</td><td>Mycat中间件服务器</td></tr><tr><td>192.168.200.210</td><td>MySQL</td><td>分片服务器</td></tr><tr><td>192.168.200.213</td><td>MySQL</td><td>分片服务器</td></tr><tr><td>192.168.200.214</td><td>MySQL</td><td>分片服务器</td></tr></tbody></table><p><a href="assets/MyCat%E5%AE%89%E8%A3%85%E6%96%87%E6%A1%A3.pdf">MyCat安装文档.pdf</a></p><h3 id="_2-2-目录结构" tabindex="-1">2.2 目录结构 <a class="header-anchor" href="#_2-2-目录结构" aria-label="Permalink to “2.2 目录结构”">​</a></h3><ul><li><p>bin : 存放可执行文件，用于启动停止mycat</p></li><li><p>conf：存放mycat的配置文件</p></li><li><p>lib：存放mycat的项目依赖包（jar）</p></li><li><p>logs：存放mycat的日志文件</p></li></ul><h3 id="_2-3-概念介绍" tabindex="-1">2.3 概念介绍 <a class="header-anchor" href="#_2-3-概念介绍" aria-label="Permalink to “2.3 概念介绍”">​</a></h3><p><img src="`+V+`" alt="04a5a1a44f09439bb2c364e6fe67bc7apng" width="1444" height="723"></p><ul><li>Mycat本身不直接存储数据，只负责管理数据请求的路由和分发，而实际的数据存储由后端数据库完成</li></ul><h2 id="_3-mycat入门" tabindex="-1">3.Mycat入门 <a class="header-anchor" href="#_3-mycat入门" aria-label="Permalink to “3.Mycat入门”">​</a></h2><h3 id="_3-1-需求" tabindex="-1">3.1 需求 <a class="header-anchor" href="#_3-1-需求" aria-label="Permalink to “3.1 需求”">​</a></h3><p>以 tb_order 表为例：由于 tb_order 表中数据量很大，磁盘IO及容量都到达了瓶颈，现在需要对 tb_order 表进行数据分片，分为三个数据节点，每一个节点主机位于不同的服务器上。</p><p><img src="`+W+`" alt="496b6b81a7ad411f9a2e87ec7fb24572png" width="672" height="472"></p><h3 id="_3-2-环境准备" tabindex="-1">3.2 环境准备 <a class="header-anchor" href="#_3-2-环境准备" aria-label="Permalink to “3.2 环境准备”">​</a></h3><ol><li><p>关闭三台服务器的防火墙</p></li><li><p>分别在三台服务器里创建数据库（分库、库名要一致）</p></li></ol><p><img src="`+P+`" alt="8a0945fc78ee4742a14b3f97debea572png" width="1008" height="655"></p><h3 id="_3-3-分片配置" tabindex="-1">3.3 分片配置 <a class="header-anchor" href="#_3-3-分片配置" aria-label="Permalink to “3.3 分片配置”">​</a></h3><h4 id="schema-xml" tabindex="-1">schema.xml <a class="header-anchor" href="#schema-xml" aria-label="Permalink to “schema.xml”">​</a></h4><p><img src="`+M+`" alt="b36228de457b428ea1ea3cba624736fapng" width="1584" height="676"></p><h4 id="server-xml" tabindex="-1">server.xml <a class="header-anchor" href="#server-xml" aria-label="Permalink to “server.xml”">​</a></h4><p>配置mycat的用户及用户的权限信息：</p><p><img src="`+Y+`" alt="975e5bfab23a4ae1b29d28237314206cpng" width="959" height="474"></p><h3 id="_3-4-启动服务" tabindex="-1">3.4 启动服务 <a class="header-anchor" href="#_3-4-启动服务" aria-label="Permalink to “3.4 启动服务”">​</a></h3><p>切换到Mycat的安装目录，执行如下指令，启动Mycat：</p><div class="language-PowerShell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">PowerShell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">## 启动</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bin</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mycat start</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">## 停止</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bin</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mycat stop</span></span></code></pre></div><p><strong>Mycat启动之后，占用端口号 8066</strong></p><p>启动完毕之后，可以查看logs目录下的启动日志，查看Mycat是否启动完成</p><p><img src="`+B+`" alt="9ce6611358a14d9d86be0789045f161cpng" width="1227" height="273"></p><p><img src="`+j+`" alt="63248bf20d214d1dbca56fc859a5026epng" width="1549" height="713"></p><h3 id="_3-5-分片测试" tabindex="-1">3.5 分片测试 <a class="header-anchor" href="#_3-5-分片测试" aria-label="Permalink to “3.5 分片测试”">​</a></h3><p>通过如下指令，就可以连接并登陆MyCat：</p><div class="language-PowerShell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">PowerShell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysql </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">192.168</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200.210</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">P </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8066</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uroot </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p123456</span></span></code></pre></div><p>然后就可以在MyCat中来创建表，并往表结构中插入数据，查看数据在MySQL中的分布情况</p><p><img src="`+q+`" alt="1ee4e8d34f05484daead3f550c0df86fpng" width="874" height="382"></p><h2 id="_4-mycat配置" tabindex="-1">4.Mycat配置 <a class="header-anchor" href="#_4-mycat配置" aria-label="Permalink to “4.Mycat配置”">​</a></h2><h3 id="_4-1-schema-xml" tabindex="-1">4.1 schema.xml <a class="header-anchor" href="#_4-1-schema-xml" aria-label="Permalink to “4.1 schema.xml”">​</a></h3><p>schema.xml 作为MyCat中最重要的配置文件之一 , 涵盖了MyCat的逻辑库、逻辑表、分片规则、分片节点及数据源的配置</p><p>主要包含以下三组标签：</p><ul><li><p>schema标签</p></li><li><p>datanode标签</p></li><li><p>datahost标签</p></li></ul><p><img src="`+U+`" alt="68ba34f3077f44948d9365a4210e9e77png" width="1562" height="684"></p><h4 id="schema标签" tabindex="-1">schema标签 <a class="header-anchor" href="#schema标签" aria-label="Permalink to “schema标签”">​</a></h4><p>schema 标签用于定义 MyCat实例中的逻辑库 , 一个MyCat实例中, 可以有多个逻辑库 , 可以通过 schema 标签来划分不同的逻辑库。MyCat中的逻辑库的概念，等同于MySQL中的database概念 , 需要操作某个逻辑库下的表时, 也需要切换逻辑库(use xxx)。</p><p><strong>核心属性</strong>：</p><ul><li><p>name：指定自定义的逻辑库库名</p></li><li><p>checkSQLschema：在SQL语句操作时指定了数据库名称，执行时是否自动去除；true：自动去除，false：不自动去除</p></li><li><p>sqlMaxLimit：如果未指定limit进行查询，列表查询模式查询多少条记录</p></li></ul><p><img src="`+k+`" alt="9ab26fbed280435188fb07b6592a2089png" width="1211" height="168"></p><p>table 标签定义了MyCat中逻辑库schema下的逻辑表 , 所有需要拆分的表都需要在table标签中定义 。</p><p><strong>核心属性</strong>：</p><ul><li><p>name：定义逻辑表表名，在该逻辑库下唯一</p></li><li><p>dataNode：定义逻辑表所属的dataNode，该属性需要与dataNode标签中name对应；多个dataNode逗号分隔</p></li><li><p>rule：分片规则的名字，分片规则名字是在rule.xml中定义的</p></li><li><p>primaryKey：逻辑表对应真实表的主键</p></li><li><p>type：逻辑表的类型，目前逻辑表只有全局表和普通表，如果未配置，就是普通表；全局表，配置为 global</p></li></ul><p><img src="`+L+`" alt="7355a7ed30f64537ac5665c4387c4e91png" width="1129" height="179"></p><h4 id="datanode标签" tabindex="-1">dataNode标签 <a class="header-anchor" href="#datanode标签" aria-label="Permalink to “dataNode标签”">​</a></h4><p>dataNode标签中定义了MyCat中的数据节点, 也就是我们通常说的数据分片。一个dataNode标签就是一个独立的数据分片。</p><p><strong>核心属性</strong>：</p><ul><li><p>name：定义数据节点名</p></li><li><p>dataHost：数据库实例主机名称，引用自 dataHost 标签中name属性</p></li><li><p>database：定义分片所属数据库</p></li></ul><p><img src="`+K+`" alt="1cd9270e76b342899cc1ad5dea7c290fpng" width="1047" height="163"></p><h4 id="datahost标签" tabindex="-1">dataHost标签 <a class="header-anchor" href="#datahost标签" aria-label="Permalink to “dataHost标签”">​</a></h4><p>该标签在MyCat逻辑库中作为底层标签存在, 直接定义了具体的数据库实例、读写分离、心跳语句。</p><p><strong>核心属性</strong>：</p><ul><li><p>name：唯一标识，供上层标签使用</p></li><li><p>maxCon/minCon：最大连接数/最小连接数</p></li><li><p>balance：负载均衡策略，取值 0,1,2,3</p></li><li><p>writeType：写操作分发方式（0：写操作转发到第一个writeHost，第一个挂了，切换到第二个；1：写操作随机分发到配置的writeHost）</p></li><li><p>dbDriver：数据库驱动，支持 native、jdbc</p></li></ul><p><img src="`+H+`" alt="e98824e933df478d9615a059d399318apng" width="1530" height="216"></p><h3 id="_4-2-rule-xml" tabindex="-1">4.2 rule.xml <a class="header-anchor" href="#_4-2-rule-xml" aria-label="Permalink to “4.2 rule.xml”">​</a></h3><p>rule.xml中定义所有拆分表的规则, 在使用过程中可以灵活的使用分片算法, 或者对同一个分片算法使用不同的参数, 它让分片过程可配 置化。</p><p>主要包含两类标签：</p><ul><li><p>tableRule</p></li><li><p>Function</p></li></ul><p><img src="`+J+`" alt="b5915b3f499c4e2a86bab937eeb14e71png" width="1195" height="512"></p><h3 id="_4-3-server-xml" tabindex="-1">4.3 server.xml <a class="header-anchor" href="#_4-3-server-xml" aria-label="Permalink to “4.3 server.xml”">​</a></h3><p><a href="assets/server.xml">server.xml</a></p><p>server.xml配置文件包含了MyCat的系统配置信息。</p><p>主要有两个重要的标签：</p><ul><li><p>system</p></li><li><p>user</p></li></ul><h4 id="system标签" tabindex="-1">system标签 <a class="header-anchor" href="#system标签" aria-label="Permalink to “system标签”">​</a></h4><p>对应的系统配置项及其含义，参考<a href="https://mcnerzykwkel.feishu.cn/sheets/JkgNsdO9Ch7H7ft8J6scJCPAnAf?from=from_copylink" target="_blank" rel="noreferrer">server系统配置信息含义</a>：</p><p><img src="`+N+`" alt="6f83da62a29f424f8f9338a7af248373png" width="897" height="170"></p><h4 id="user标签" tabindex="-1">user标签 <a class="header-anchor" href="#user标签" aria-label="Permalink to “user标签”">​</a></h4><p><img src="`+r+`" alt="9cae264fc45a4ee7b3d8058d65e0543apng" width="1420" height="598"></p><h2 id="_5-mycat分片" tabindex="-1">5.Mycat分片 <a class="header-anchor" href="#_5-mycat分片" aria-label="Permalink to “5.Mycat分片”">​</a></h2><h3 id="_5-1-垂直拆分" tabindex="-1">5.1 垂直拆分 <a class="header-anchor" href="#_5-1-垂直拆分" aria-label="Permalink to “5.1 垂直拆分”">​</a></h3><p>在业务系统中, 涉及以下表结构 ,但是由于用户与订单每天都会产生大量的数据, 单台服务器的数据存储及处理能力是有限的, 可以对数据 库表进行拆分, 原有的数据库表如下：</p><p><img src="`+b+`" alt="f581f726dc9b4194a608f29557bba2eapng" width="1132" height="453"></p><h4 id="_5-1-1-准备" tabindex="-1">5.1.1 准备 <a class="header-anchor" href="#_5-1-1-准备" aria-label="Permalink to “5.1.1 准备”">​</a></h4><p>分别在三台MySQL中创建数据库 shopping。</p><p><img src="`+O+`" alt="a482742497664bb38526bedf81778d61png" width="894" height="543"></p><h4 id="_5-1-2-配置" tabindex="-1">5.1.2 配置 <a class="header-anchor" href="#_5-1-2-配置" aria-label="Permalink to “5.1.2 配置”">​</a></h4><p><img src="`+E+`" alt="f7852b13fd974344a397530706ba19f5png" width="1576" height="612"></p><p><img src="`+D+`" alt="f5e2a1aa82f9440eb3837169f59096capng" width="1087" height="669"></p><h4 id="_5-1-3-测试" tabindex="-1">5.1.3 测试 <a class="header-anchor" href="#_5-1-3-测试" aria-label="Permalink to “5.1.3 测试”">​</a></h4><p><img src="`+p+`" alt="6bac7ab29f5544bd8a09ceeddb8159ddpng" width="1466" height="571"></p><p><strong>全局表配置</strong>：对于第二个查询语句，省、市、区/县表tb_areas_provinces , tb_areas_city , tb_areas_region，是属于数据字典表，只能在本子数据库中可以使用，但是在多个业务模块中都可能会遇到，可以将其设置为全局表，利于业务操作：</p><p><img src="`+G+`" alt="2b7b36ca5e6343a8986f5ab34b2602d7png" width="1586" height="624"></p><h3 id="_5-2-水平拆分" tabindex="-1">5.2 水平拆分 <a class="header-anchor" href="#_5-2-水平拆分" aria-label="Permalink to “5.2 水平拆分”">​</a></h3><p>在业务系统中, 有一张表(日志表), 业务系统每天都会产生大量的日志数据 , 单台服务器的数据存储及处理能力是有限的, 可以对数据库表 进行拆分。</p><p><img src="`+m+`" alt="1acd604367c941f98067f35034fc37fapng" width="1215" height="467"></p><h4 id="_5-2-1-准备" tabindex="-1">5.2.1 准备 <a class="header-anchor" href="#_5-2-1-准备" aria-label="Permalink to “5.2.1 准备”">​</a></h4><p>分别在三台MySQL中创建数据库 itcast。</p><p><img src="`+u+`" alt="bf06e7dcc77e43b98b73959710ca2c04png" width="797" height="533"></p><h4 id="_5-2-2-配置" tabindex="-1">5.2.2 配置 <a class="header-anchor" href="#_5-2-2-配置" aria-label="Permalink to “5.2.2 配置”">​</a></h4><p><img src="`+T+`" alt="bd3990ba5c554d59b575c6d15cf1405cpng" width="1333" height="574"></p><h4 id="_5-2-3-测试" tabindex="-1">5.2.3 测试 <a class="header-anchor" href="#_5-2-3-测试" aria-label="Permalink to “5.2.3 测试”">​</a></h4><p><img src="`+C+`" alt="c63b1304af7b4b25a0dd85731c813029png" width="1523" height="558"></p><ul><li>在Mycat中创建表、插入数据后分表会自动创建和插入相应的数据，不需要像垂直分表那样手动创建表</li></ul><h3 id="_5-3-分片规则" tabindex="-1">5.3 分片规则 <a class="header-anchor" href="#_5-3-分片规则" aria-label="Permalink to “5.3 分片规则”">​</a></h3><h4 id="_5-3-1-分片规则-范围" tabindex="-1">5.3.1 分片规则-范围 <a class="header-anchor" href="#_5-3-1-分片规则-范围" aria-label="Permalink to “5.3.1 分片规则-范围”">​</a></h4><p>根据指定的字段及其配置的范围与数据节点的对应情况， 来决定该数据属于哪一个分片。</p><p><img src="`+d+`" alt="cbb9d259e77b4196a7707a18083f027dpng" width="669" height="397"></p><p><img src="`+w+`" alt="98d9d9db8a8d49f1a0c8f176d7d0692dpng" width="1561" height="709"></p><h4 id="_5-3-2-分片规则-取模" tabindex="-1">5.3.2 分片规则-取模 <a class="header-anchor" href="#_5-3-2-分片规则-取模" aria-label="Permalink to “5.3.2 分片规则-取模”">​</a></h4><p>根据指定的字段值与节点数量进行求模运算，根据运算结果， 来决定该数据属于哪一个分片。</p><p><img src="`+a+`" alt="d17eee3d41bd4710b4e74c820df612bbpng" width="601" height="385"></p><p><img src="`+ne+`" alt="7f487c4fb3f342dcbbbc6e9ddd39659fpng" width="1167" height="581"></p><ul><li>范围分片和取模分片只适用于数字，其他如字符串就不适用了</li></ul><h4 id="_5-3-3-分片规则-一致性hash" tabindex="-1">5.3.3 分片规则-一致性hash <a class="header-anchor" href="#_5-3-3-分片规则-一致性hash" aria-label="Permalink to “5.3.3 分片规则-一致性hash”">​</a></h4><p>所谓一致性哈希， 相同的哈希因子计算值总是被划分到相同的分区表中，不会因为分区节点的增加而改变原来数据的分区位置。</p><p><img src="`+x+`" alt="76162877031249f394aa9e2f2df65616png" width="625" height="411"></p><p><img src="`+h+`" alt="272492a8cbc74f668044c228a140084bpng" width="1226" height="649"></p><h4 id="_5-3-4-分片规则-枚举" tabindex="-1">5.3.4 分片规则-枚举 <a class="header-anchor" href="#_5-3-4-分片规则-枚举" aria-label="Permalink to “5.3.4 分片规则-枚举”">​</a></h4><p>通过在配置文件中配置可能的枚举值, 指定数据分布到不同数据节点上, 本规则适用于按照身份、性别、状态拆分数据等业务 。</p><p><img src="`+f+`" alt="e00b9ca5b6bd4d2e8e982405a68c384fpng" width="575" height="383"></p><p><img src="`+l+`" alt="28d1593c3fe2455591088876ca481591png" width="1480" height="654"></p><h4 id="_5-3-5-分片规则-应用指定" tabindex="-1">5.3.5 分片规则-应用指定 <a class="header-anchor" href="#_5-3-5-分片规则-应用指定" aria-label="Permalink to “5.3.5 分片规则-应用指定”">​</a></h4><p>运行阶段由应用自主决定路由到那个分片 , 直接根据字符子串（必须是数字）计算分片号。</p><p><img src="`+y+`" alt="8f9aeb06abdd4ab881795d460f88020bpng" width="581" height="400"></p><p><img src="`+_+`" alt="1dc371f10aaf416d8ddf4a102f8f3512png" width="1250" height="628"></p><h4 id="_5-3-6-分片规则-固定分片hash算法" tabindex="-1">5.3.6 分片规则-固定分片hash算法 <a class="header-anchor" href="#_5-3-6-分片规则-固定分片hash算法" aria-label="Permalink to “5.3.6 分片规则-固定分片hash算法”">​</a></h4><p>该算法类似于十进制的求模运算，但是为二进制的操作，例如，取 id 的二进制低 10 位 与 1111111111 进行位 &amp; 运算。</p><p><img src="`+g+`" alt="2a47a6c5bcc74bafabf05e67bbd6e439png" width="1060" height="435"></p><p><img src="`+R+`" alt="501261a36f8043a396755477312ee91cpng" width="1513" height="649"></p><h4 id="_5-3-7-分片规则-字符串hash解析" tabindex="-1">5.3.7 分片规则-字符串hash解析 <a class="header-anchor" href="#_5-3-7-分片规则-字符串hash解析" aria-label="Permalink to “5.3.7 分片规则-字符串hash解析”">​</a></h4><p>截取字符串中的指定位置的子字符串, 进行hash算法， 算出分片。</p><p><img src="`+i+`" alt="8d568bef55cd49e4a1a883903b3b61b5png" width="584" height="406"></p><p><img src="`+z+`" alt="71521610a4fd4ae6ad080e6baf3e40a6png" width="1401" height="642"></p><h4 id="_5-3-8-分片规则-按-天-日期分片" tabindex="-1">5.3.8 分片规则-按（天）日期分片 <a class="header-anchor" href="#_5-3-8-分片规则-按-天-日期分片" aria-label="Permalink to “5.3.8 分片规则-按（天）日期分片”">​</a></h4><p><img src="`+v+`" alt="f16c90a934b54358b0fa77a7d3981e80png" width="667" height="397"></p><p><img src="`+s+`" alt="ea922819133e4b22ba8459c146ac2fc0png" width="1423" height="639"></p><h4 id="_5-3-9-分片规则-自然月" tabindex="-1">5.3.9 分片规则-自然月 <a class="header-anchor" href="#_5-3-9-分片规则-自然月" aria-label="Permalink to “5.3.9 分片规则-自然月”">​</a></h4><p>使用场景为按照月份来分片, 每个自然月为一个分片。</p><p><img src="`+c+`" alt="48f12e57ca4940b3918c283503887b58png" width="599" height="405"></p><p><img src="`+S+`" alt="b142eb7600df4aa7b15e00dea64987d2png" width="1263" height="635"></p><h2 id="_6-mycat管理及监控" tabindex="-1">6.Mycat管理及监控 <a class="header-anchor" href="#_6-mycat管理及监控" aria-label="Permalink to “6.Mycat管理及监控”">​</a></h2><h3 id="_6-1-mycat原理" tabindex="-1">6.1 Mycat原理 <a class="header-anchor" href="#_6-1-mycat原理" aria-label="Permalink to “6.1 Mycat原理”">​</a></h3><p>Mycat从客户端接收到信息后，会先进行SQL语句解析，进行分片分析和路由分析，根据分片规则将 SQL 路由到相应的数据库节点，Mycat 支持读写分离，将写操作发往主库，读操作发往从库，服务器处理运行Mycat路由过来的SQL后，将运行结果返回给Mycat，Mycat从各节点获取数据后，在中间件层进行结果合并和聚合处理，如果SQL语句有排序操作和分页操作，会对聚合后的数据进行排序处理和分页处理，最后把最终结果返回给客户端。</p><p><img src="`+Z+`" alt="4d8be94c3c6745469180fe3306d3c0f3png" width="1550" height="675"></p><h3 id="_6-2-mycat管理" tabindex="-1">6.2 Mycat管理 <a class="header-anchor" href="#_6-2-mycat管理" aria-label="Permalink to “6.2 Mycat管理”">​</a></h3><p>Mycat默认开通2个端口，可以在<a href="https://mcnerzykwkel.feishu.cn/file/HV1Lb4yr5ojkhfxzctkcYyihnzd?from=from_copylink" target="_blank" rel="noreferrer">server.xml</a>中进行修改：</p><ul><li><p>8066 数据访问端口，即进行 DML 和 DDL 操作</p></li><li><p>9066 数据库管理端口，即 mycat 服务管理控制功能，用于管理mycat的整个集群状态</p></li></ul><div class="language-PowerShell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">PowerShell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysql </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">192.168</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200.210</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">P </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9066</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uroot </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p123456</span></span></code></pre></div><table tabindex="0"><thead><tr><th>命令</th><th>含义</th></tr></thead><tbody><tr><td>show @@help</td><td>查看Mycat管理工具帮助文档</td></tr><tr><td>show @@version</td><td>查看Mycat的版本</td></tr><tr><td>show @@config</td><td>重新加载Mycat的配置文件</td></tr><tr><td>show @@datasource</td><td>查看Mycat的数据源信息</td></tr><tr><td>show @@datanode</td><td>查看Mycat现有的分片节点信息</td></tr><tr><td>show @@threadpool</td><td>查看Mycat的线程池信息</td></tr><tr><td>show @@sql</td><td>查看执行的SQL</td></tr><tr><td>show @@sql.sum</td><td>查看执行的SQL统计</td></tr></tbody></table><h3 id="_6-3-mycat-eye" tabindex="-1">6.3 Mycat-eye <a class="header-anchor" href="#_6-3-mycat-eye" aria-label="Permalink to “6.3 Mycat-eye”">​</a></h3><p>Mycat-web（Mycat-eye）是对mycat-server提供监控服务，功能不局限于对mycat-server使用。他通过JDBC连接对Mycat、Mysql监控，监控远程服务器（目前仅限于linux系统）的cpu、内存、网络、磁盘。</p><p>Mycat-eye运行过程中需要依赖zookeeper，因此需要先安装zookeeper。</p><p>安装：Zookeeper安装和MyCat-web安装</p><p><a href="assets/MyCat-web%E5%AE%89%E8%A3%85%E6%96%87%E6%A1%A3.pdf">MyCat-web安装文档.pdf</a></p><p>访问：<a href="http://192" target="_blank" rel="noreferrer">http://192</a>.168.200.210:8082/mycat</p><p>配置：</p><p><img src="`+o+`" alt="84bf791221bc46218ccb8f5109fd97afpng" width="855" height="567"></p>`,166)]])}var ae=n(re,[[`render`,ie]]);export{$ as __pageData,ae as default};